import{_ as t}from"./chunks/gather-evidence.CFBdlZLj.js";import{_ as a,o,c as r,ak as i}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Your first failure, explained","description":"Read one failing test in the dashboard from top to bottom: the headline, the likely cause, the situation, the next step and the evidence.","frontmatter":{"title":"Your first failure, explained","description":"Read one failing test in the dashboard from top to bottom: the headline, the likely cause, the situation, the next step and the evidence.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/first-failure.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/first-failure.html"}],["meta",{"property":"og:title","content":"Your first failure, explained | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Read one failing test in the dashboard from top to bottom: the headline, the likely cause, the situation, the next step and the evidence."}]]},"headers":[],"relativePath":"guide/first-failure.md","filePath":"guide/first-failure.md","lastUpdated":1790891729000}'),n={name:"guide/first-failure.md"};function s(l,e,h,d,c,u){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="your-first-failure-explained" tabindex="-1">Your first failure, explained <a class="header-anchor" href="#your-first-failure-explained" aria-label="Permalink to &quot;Your first failure, explained&quot;">​</a></h1><p>You&#39;ve landed your first run (<a href="./getting-started.html">Getting started</a>) and one test is red. This page walks through reading it. Piwi lays a failing execution out <strong>diagnosis-first</strong>, in one column read top to bottom: <em>what</em> broke, <em>why</em>, <em>what to do next</em>, then the evidence.</p><p>Open the failing test from the run page (click its row) to reach its <strong>execution page</strong>.</p><figure><img src="'+t+'" alt="A failing execution laid out diagnosis-first: one situation block with headline, most likely, situation and next step, and one evidence card with tabs"><figcaption>One failing execution, read top to bottom: the situation block that says what broke, what is most likely and what to do, then the evidence.</figcaption></figure><p>The top of the page is one <strong>situation block</strong>. Above its heading, a small <strong>identity</strong> line carries the status, the test title, Playwright marks such as <code>@fixme</code> or <code>@slow</code>, and whether the test is quarantined. The lines below it are the rest of this page, in order.</p><h2 id="_1-the-headline-what-broke" tabindex="-1">1. The headline: what broke <a class="header-anchor" href="#_1-the-headline-what-broke" aria-label="Permalink to &quot;1. The headline: what broke&quot;">​</a></h2><p>The heading is a plain-English sentence built from the Playwright error, before you read a word of the raw error itself:</p><blockquote><p><code>getByRole(&#39;button&#39;, { name: &#39;Pay&#39; }) never became enabled — click timed out after 30 s</code></p></blockquote><p>It is read from the action or matcher, the locator, the expected and received values and the timeout; an unknown error shape falls back to the error&#39;s first line. A failure in a hook or fixture says where it happened (<code>In beforeEach: …</code>), and an <code>expect</code> you gave a message leads with it (<code>&quot;cart shows the item&quot; failed: …</code>). The verbatim error is one click away under <strong>Raw error</strong>: Piwi never rewrites it, it only leads with a readable summary. The same headline names the test on the run page, in <a href="/features/notifications.html">alerts</a>, in the <a href="/features/pr-feedback.html">pull-request comment</a>, in the MCP tools and in your terminal, so you recognize it everywhere.</p><h2 id="_2-most-likely-why" tabindex="-1">2. Most likely: why <a class="header-anchor" href="#_2-most-likely-why" aria-label="Permalink to &quot;2. Most likely: why&quot;">​</a></h2><p>Under the headline, the <strong>Most likely</strong> line gives you the one explanation, not a pile of them. It is built from <strong><a href="/features/evidence.html#clues">clues</a></strong>: deterministic, rule-based findings correlated from the evidence, with <em>no model involved</em>. When the clues match a known pattern (some patterns need only one clue), the line is a <a href="./concepts.html#story">story</a>, one sentence that chains them:</p><blockquote><p><em>&quot;the Pay button stayed disabled because POST /api/checkout/quote was still in flight (28 s); the console said so 1.5 s before the click gave up&quot;</em></p></blockquote><p>Otherwise it is the cluster&#39;s completed <a href="/features/ai-diagnosis.html">AI diagnosis</a>, else the strongest clue. It carries a strength (<em>Strong</em>, <em>Medium</em> or <em>Weak</em>, or the diagnosis&#39;s confidence) and how many clues <strong>agree</strong>; an <strong>All clues</strong> disclosure lists every clue, each with a <strong>citation</strong> to the evidence it came from. Click a citation and the page jumps to the proof. When no rule fires, the line is absent. The <a href="/reference/clues.html">Clue rules</a> page lists every rule.</p><h2 id="_3-the-situation-what-s-going-on" tabindex="-1">3. The situation: what&#39;s going on <a class="header-anchor" href="#_3-the-situation-what-s-going-on" aria-label="Permalink to &quot;3. The situation: what&#39;s going on&quot;">​</a></h2><p>Below the explanation, the <strong>situation</strong> sentence puts the failure in context in one line: since when it&#39;s been failing (the first failing run), this run&#39;s commit and author, how many other tests share the same cause and the <a href="/features/failure-clusters.html">cluster</a> they join, with its triage status and whether an earlier fix regressed, and who owns it. An exceptional case (a new regression, a pass on retry, a newly flaky test, an infrastructure failure) leads the sentence as its one badge.</p><h2 id="_4-next-what-to-do" tabindex="-1">4. Next: what to do <a class="header-anchor" href="#_4-next-what-to-do" aria-label="Permalink to &quot;4. Next: what to do&quot;">​</a></h2><p>The <strong>Next</strong> line names the one thing to do, chosen for you rather than offered as a menu: apply the diagnosed patch, replace the <a href="/features/locator-healing.html">broken locator</a>, reproduce it locally, re-run in CI, or mark the cluster resolved. Where the work is a code change, the step&#39;s <strong>···</strong> menu copies the exact command to re-run this test (<strong>Copy retry command</strong>). The full policy is on the <a href="/features/fix-plans.html#the-next-step">fix-plans page</a>.</p><p>The block closes on a <strong>facts</strong> line, one size smaller: the failing file and line (open it in your IDE), browser and viewport, duration against its average, the attempts, the branch, and the CI build. A <strong>Details</strong> popover holds the rest, and <strong>Raw error</strong> shows the verbatim error with a <strong>Copy failure</strong> action.</p><h2 id="_5-the-evidence-see-it" tabindex="-1">5. The evidence: see it <a class="header-anchor" href="#_5-the-evidence-see-it" aria-label="Permalink to &quot;5. The evidence: see it&quot;">​</a></h2><p>One <strong>evidence card</strong> with tabs (<strong>Timeline, Screen, Source, Network, Console, State, Performance</strong>, plus <strong>Attempts</strong> when the test retried) holds everything captured. It opens on <strong>Timeline</strong> when it can place two or more steps, requests or console entries, otherwise on the tab the leading clue cites, and a click on any citation switches tabs for you. The one to know first is <strong>Timeline</strong>: it places the test&#39;s steps, console entries, network requests and backend logs on a single clock and marks the <strong>moment of failure</strong>, so &quot;console (1) / network (3)&quot; becomes <em>what the app was doing when the test gave up</em>. <strong>Screen</strong> holds the failure screenshot, the visual diff against the last green run, and the failure-time page state; <strong>Source</strong> shows the test source as a real call stack, so a failure inside a helper shows the helper. Each tab is described on <a href="/features/evidence.html">Failure evidence</a>.</p><div class="tip custom-block"><p class="custom-block-title">Most of this needs one file</p><p>The error, trace, headline and clustering work with the reporter alone, and an uploaded trace recovers the console, network and failure-time snapshot. Web Vitals, page state and locator healing come from the <a href="./capture-fixtures.html">capture fixtures</a>, one file in your test setup. A tab that needs them and never received any data is left out, and until you decide on the fixtures one footer line names what they would add.</p></div><h2 id="_6-more-ways-to-fix" tabindex="-1">6. More ways to fix <a class="header-anchor" href="#_6-more-ways-to-fix" aria-label="Permalink to &quot;6. More ways to fix&quot;">​</a></h2><p>Below the evidence, <strong>More ways to fix</strong> is the folded toolbox holding every <em>other</em> way to fix, verify or reproduce, each section collapsed to one line. The section the <strong>Next</strong> step points at is already open:</p><ul><li>a <strong><a href="/features/locator-healing.html">replacement locator</a></strong> when a locator broke, ranked by stability and in your suite&#39;s own style;</li><li>the <strong><a href="/features/ai-diagnosis.html">AI diagnosis</a></strong> and its validated patch, when you&#39;ve configured a model (optional, and grounded in your real diff);</li><li><strong>verify</strong> (re-run in CI or locally), <strong>reproduce and bisect</strong>, whether this failure was <strong>fixed before</strong>, the tests it <strong>blocked</strong>, and the <strong><a href="/features/fix-plans.html">fix plan</a></strong> as Markdown.</li></ul><p>Below the toolbox, a <strong>history</strong> strip shows this test&#39;s recent executions and how long it has been failing.</p><h2 id="you-re-not-reading-it-alone" tabindex="-1">You&#39;re not reading it alone <a class="header-anchor" href="#you-re-not-reading-it-alone" aria-label="Permalink to &quot;You&#39;re not reading it alone&quot;">​</a></h2><p>This execution is one member of a <strong><a href="/features/failure-clusters.html">failure cluster</a></strong>: Piwi groups every test that failed for the same reason, so forty red tests become three problems you triage once. Once a later run passes every test it covers, the cluster records <a href="/features/failure-clusters.html#did-the-fix-work">whether the fix held</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/evidence.html">Failure evidence</a>: each evidence tab, attempts, the page diff and the trace views</li><li><a href="/reference/clues.html">Clue rules</a>: every rule behind the <strong>Most likely</strong> line</li><li><a href="/features/failure-clusters.html">Failure clusters &amp; the inbox</a>: triaging failures as groups</li><li><a href="./capture-fixtures.html">Capture fixtures</a>: the one file that unlocks the richer evidence</li><li><a href="./concepts.html">Core concepts</a>: run, execution, cluster, fingerprint, baseline</li></ul>',29)])])}const m=a(n,[["render",s]]);export{p as __pageData,m as default};
